int checks=0,failures=0;
void Check(bool p,const char*n){++checks;if(!p){++failures;cerr<<"FAIL "<<n<<"\n";}}
template<class P>bool Pump(P ready,int limit=3000){QElapsedTimer t;t.start();while(!ready()&&t.elapsed()<limit){QCoreApplication::processEvents(QEventLoop::AllEvents,5);QThread::msleep(1);}return ready();}
QPushButton*Button(GoogleDriveBackupDialog*d,const char*n){for(auto*b:d->findChildren<QPushButton*>())if(b->text()==n)return b;return nullptr;}
GoogleDriveBackupDialog* Open(){auto*d=new GoogleDriveBackupDialog;Check(Pump([&]{return Button(d,"CloudBackup.BackupNow")->isEnabled();}),"fixture dialog connected");return d;}
string Value(const char*k){auto*v=config_get_string(App()->GetUserConfig(),"GoogleDriveBackup",k);return v?v:"";}
void Put(const char*k,const char*v){config_set_string(App()->GetUserConfig(),"GoogleDriveBackup",k,v);}
